import { createHash, createHmac, timingSafeEqual } from 'node:crypto'

export type CheckoutRequest = {
  transactionId: string
  amountCents: number
  currency: 'usd'
  description: string
  idempotencyKey: string
  successUrl: string
  cancelUrl: string
}

export type VerifiedPaymentEvent = {
  id: string
  type: string
  createdAt: Date
  signatureTimestamp: Date
  transactionId: string
  providerTransactionId?: string
  providerSessionId?: string
  providerRefundId?: string
  amountCents?: number
  providerStatus?: string
  rawDigest: string
}

export function paymentsEnabled() {
  return process.env.PAYMENTS_ENABLED?.trim().toLowerCase() === 'true'
}

function assertPaymentsEnabled() {
  if (!paymentsEnabled()) throw new Error('Payments are disabled for this deployment')
}

function configured(name: string) {
  assertPaymentsEnabled()
  const value = process.env[name]?.trim()
  if (!value) throw new Error(`Payment provider is not configured: ${name}`)
  return value
}

async function stripeRequest(path: string, body: URLSearchParams, idempotencyKey: string) {
  const response = await fetch(`https://api.stripe.com/v1/${path}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${configured('STRIPE_SECRET_KEY')}`,
      'Content-Type': 'application/x-www-form-urlencoded',
      'Idempotency-Key': idempotencyKey,
    },
    body,
    signal: AbortSignal.timeout(15_000),
  })
  const payload = await response.json() as any
  if (!response.ok) {
    const error = new Error('Payment provider request failed') as Error & { code?: string }
    error.code = String(payload?.error?.code || payload?.error?.type || `HTTP_${response.status}`).slice(0, 100)
    throw error
  }
  return payload
}

function signatureParts(header: string) {
  const values = new Map<string, string[]>()
  for (const part of header.split(',')) {
    const [key, value] = part.trim().split('=', 2)
    if (!key || !value) continue
    values.set(key, [...(values.get(key) || []), value])
  }
  return { timestamp: values.get('t')?.[0], signatures: values.get('v1') || [] }
}

export const stripePaymentProvider = {
  key: 'stripe',
  async createCheckout(request: CheckoutRequest) {
    const body = new URLSearchParams({
      mode: 'payment',
      success_url: request.successUrl,
      cancel_url: request.cancelUrl,
      'line_items[0][quantity]': '1',
      'line_items[0][price_data][currency]': request.currency,
      'line_items[0][price_data][unit_amount]': String(request.amountCents),
      'line_items[0][price_data][product_data][name]': request.description,
      'metadata[openfront_transaction_id]': request.transactionId,
      'payment_intent_data[metadata][openfront_transaction_id]': request.transactionId,
    })
    const payload = await stripeRequest('checkout/sessions', body, request.idempotencyKey)
    if (!payload.id || !payload.url) throw new Error('Payment provider returned incomplete checkout evidence')
    return { providerSessionId: String(payload.id), checkoutUrl: String(payload.url), providerTransactionId: payload.payment_intent ? String(payload.payment_intent) : undefined }
  },
  async createRefund(input: { providerTransactionId: string; amountCents: number; reason: string; idempotencyKey: string; refundId: string; transactionId: string }) {
    const body = new URLSearchParams({
      payment_intent: input.providerTransactionId,
      amount: String(input.amountCents),
      reason: 'requested_by_customer',
      'metadata[openfront_refund_id]': input.refundId,
      'metadata[openfront_transaction_id]': input.transactionId,
      'metadata[openfront_reason]': input.reason.slice(0, 200),
    })
    const payload = await stripeRequest('refunds', body, input.idempotencyKey)
    if (!payload.id || !payload.status) throw new Error('Payment provider returned incomplete refund evidence')
    return { providerRefundId: String(payload.id), status: String(payload.status) }
  },
  verifyWebhook(rawBody: string, signatureHeader: string, now = Date.now()): VerifiedPaymentEvent {
    const secret = configured('STRIPE_WEBHOOK_SECRET')
    const { timestamp, signatures } = signatureParts(signatureHeader)
    if (!timestamp || signatures.length === 0 || !/^\d+$/.test(timestamp)) throw new Error('Invalid payment webhook signature')
    const ageSeconds = Math.abs(Math.floor(now / 1000) - Number(timestamp))
    if (ageSeconds > 300) throw new Error('Expired payment webhook signature')
    const expected = createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest()
    const valid = signatures.some(value => {
      if (!/^[a-f0-9]{64}$/i.test(value)) return false
      return timingSafeEqual(expected, Buffer.from(value, 'hex'))
    })
    if (!valid) throw new Error('Invalid payment webhook signature')
    const event = JSON.parse(rawBody)
    const object = event?.data?.object || {}
    const transactionId = String(object?.metadata?.openfront_transaction_id || '')
    if (!event?.id || !event?.type || !transactionId) throw new Error('Payment webhook is missing Openfront transaction evidence')
    return {
      id: String(event.id),
      type: String(event.type),
      createdAt: new Date(Number(event.created || timestamp) * 1000),
      signatureTimestamp: new Date(Number(timestamp) * 1000),
      transactionId,
      providerTransactionId: object.payment_intent ? String(object.payment_intent) : object.object === 'payment_intent' ? String(object.id) : undefined,
      providerSessionId: object.object === 'checkout.session' ? String(object.id) : undefined,
      providerRefundId: object.object === 'refund' ? String(object.id) : undefined,
      amountCents: Number(object.amount_received ?? object.amount_total ?? object.amount ?? 0) || undefined,
      providerStatus: object.payment_status ? String(object.payment_status) : object.status ? String(object.status) : undefined,
      rawDigest: createHash('sha256').update(rawBody).digest('hex'),
    }
  },
}

export function getPaymentProvider(key: string) {
  assertPaymentsEnabled()
  if (key !== stripePaymentProvider.key) throw new Error('Unsupported payment provider')
  return stripePaymentProvider
}
