export type PasswordResetEnvironment = Record<string, string | undefined>

function configuredOrigin(value: string, label: string) {
  let url: URL
  try {
    url = new URL(value)
  } catch {
    throw new Error(`${label} must be an absolute HTTP or HTTPS URL`)
  }
  if ((url.protocol !== 'http:' && url.protocol !== 'https:') || url.username || url.password) {
    throw new Error(`${label} must be a credential-free HTTP or HTTPS origin`)
  }
  return url.origin
}

/**
 * Resolve password-reset links from trusted configuration only. Portless and
 * ordinary local development work without request-controlled Host headers or a
 * custom URL, while production still requires a canonical configured origin.
 */
export function resolvePasswordResetOrigin(
  env: PasswordResetEnvironment = process.env
) {
  for (const [label, value] of [
    ['SMTP_STORE_LINK', env.SMTP_STORE_LINK],
    ['NEXT_PUBLIC_SITE_URL', env.NEXT_PUBLIC_SITE_URL],
    ['PORTLESS_URL', env.PORTLESS_URL],
  ] as const) {
    if (value?.trim()) return configuredOrigin(value.trim(), label)
  }

  if (env.NODE_ENV === 'production') {
    throw new Error('SMTP_STORE_LINK or NEXT_PUBLIC_SITE_URL is required in production')
  }

  const port = env.PORT?.trim()
  if (port) {
    if (!/^\d+$/.test(port) || Number(port) < 1 || Number(port) > 65535) {
      throw new Error('PORT must be an integer from 1 to 65535')
    }
    return `http://127.0.0.1:${port}`
  }

  return 'http://127.0.0.1:3000'
}
