const trackingFieldUi = {
  createView: { fieldMode: 'hidden' as const },
  itemView: { fieldMode: 'read' as const },
}

export const trackingFields = {
  createdAt: timestamp({
    access: {
      create: () => false,
      update: () => false,
    },
    defaultValue: { kind: 'now' },
    db: { isNullable: false },
    label: 'Created At',
    ui: trackingFieldUi,
  }),
  updatedAt: timestamp({
    access: {
      create: () => false,
      update: () => false,
    },
    defaultValue: { kind: 'now' },
    db: { isNullable: false, updatedAt: true },
    label: 'Updated At',
    ui: trackingFieldUi,
  }),
}
