import { timingSafeEqual } from 'node:crypto'
import { parse, visit } from 'graphql'
import { resolveInternalGraphqlSecret } from '../../dashboard/lib/internalGraphqlAuth'

const internalAuthSecret = resolveInternalGraphqlSecret()
const protectedAuthOperations = new Set([
  'authenticateUserWithPassword',
  'sendUserPasswordResetLink',
  'redeemUserPasswordResetToken',
  'createInitialUser',
  'registerCustomerAccount',
])

export function containsProtectedAuthOperation(payload: any) {
  const requests = Array.isArray(payload) ? payload : [payload]
  return requests.some((request) => {
    if (!request || typeof request.query !== 'string') return false
    let protectedField = false
    try {
      visit(parse(request.query), {
        Field(node) {
          if (protectedAuthOperations.has(node.name.value)) protectedField = true
        },
      })
    } catch {
      return false
    }
    return protectedField
  })
}

export function validInternalAuthHeader(value: string | null) {
  if (!value || internalAuthSecret.length < 32) return false
  const supplied = Buffer.from(value)
  const expected = Buffer.from(internalAuthSecret)
  return supplied.length === expected.length && timingSafeEqual(supplied, expected)
}
