import { createHmac, timingSafeEqual } from 'node:crypto'

export type PublicSubmissionWorkflow =
  | 'inquiry'
  | 'test-drive'
  | 'trade-in'
  | 'financing'
  | 'service'

export const PUBLIC_SUBMISSION_TOKEN_MAX_AGE_MS = 5 * 60 * 1000
const TOKEN_MAX_LENGTH = 2_048
const LOCAL_ONLY_SECRET = 'local-public-submission-policy-secret-change-me'

function policySecret() {
  const configured = (
    process.env.PUBLIC_SUBMISSION_SECRET ||
    process.env.INTERNAL_GRAPHQL_SECRET ||
    process.env.SESSION_SECRET ||
    ''
  ).trim()
  if (process.env.NODE_ENV === 'production' && configured.length < 32) {
    throw new Error('PUBLIC_SUBMISSION_SECRET or INTERNAL_GRAPHQL_SECRET is required in production')
  }
  return configured.length >= 32 ? configured : LOCAL_ONLY_SECRET
}

export function publicSubmissionHmac(value: string) {
  return createHmac('sha256', policySecret()).update(value).digest('hex')
}

function safeEqual(left: string, right: string) {
  const supplied = Buffer.from(left)
  const expected = Buffer.from(right)
  return supplied.length === expected.length && timingSafeEqual(supplied, expected)
}

export function createPublicSubmissionRequestToken(input: {
  workflow: PublicSubmissionWorkflow
  idempotencyKey: string
  address: string
}) {
  const issuedAt = Date.now()
  const addressHash = publicSubmissionHmac(`public-submission-address:${input.address.trim() || 'unknown'}`)
  const payload = Buffer.from(JSON.stringify({
    version: 1,
    workflow: input.workflow,
    idempotencyKey: input.idempotencyKey,
    addressHash,
    issuedAt,
  })).toString('base64url')
  return `${payload}.${publicSubmissionHmac(`public-submission-token:${payload}`)}`
}

export function trustedPublicSubmissionAddressHash(
  token: unknown,
  workflow: PublicSubmissionWorkflow,
  idempotencyKey: string
) {
  const value = typeof token === 'string' ? token : ''
  if (!value || value.length > TOKEN_MAX_LENGTH) return null
  const [payload, signature, extra] = value.split('.')
  if (
    !payload ||
    !signature ||
    extra ||
    !/^[a-f0-9]{64}$/.test(signature) ||
    !safeEqual(signature, publicSubmissionHmac(`public-submission-token:${payload}`))
  ) return null
  try {
    const parsed = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'))
    if (
      parsed.version !== 1 ||
      parsed.workflow !== workflow ||
      parsed.idempotencyKey !== idempotencyKey ||
      typeof parsed.addressHash !== 'string' ||
      !/^[a-f0-9]{64}$/.test(parsed.addressHash) ||
      typeof parsed.issuedAt !== 'number' ||
      !Number.isFinite(parsed.issuedAt) ||
      Math.abs(Date.now() - parsed.issuedAt) > PUBLIC_SUBMISSION_TOKEN_MAX_AGE_MS
    ) return null
    return parsed.addressHash as string
  } catch {
    return null
  }
}
