const LOCAL_INTERNAL_GRAPHQL_SECRET = 'openfront-dealership-local-internal-graphql-boundary-v1'

export type RuntimeEnvironment = Record<string, string | undefined>

export function sanitizeDashboardReturnPath(value: unknown) {
  const path = String(value || '').trim()
  return path === '/dashboard' || path.startsWith('/dashboard/')
    ? path
    : '/dashboard'
}

function configuredUrl(value: string, label: string) {
  let url: URL
  try {
    url = new URL(value)
  } catch {
    throw new Error(`${label} must be an absolute HTTP or HTTPS URL`)
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    throw new Error(`${label} must use HTTP or HTTPS`)
  }
  return url
}

/**
 * Keeps the protected server-to-server GraphQL boundary usable in a normal
 * local/Portless dev process without weakening production configuration.
 */
export function resolveInternalGraphqlSecret(
  env: RuntimeEnvironment = process.env
) {
  const configured = env.INTERNAL_GRAPHQL_SECRET?.trim() || ''
  if (env.NODE_ENV === 'production') {
    if (configured.length < 32) {
      throw new Error('INTERNAL_GRAPHQL_SECRET is required in production')
    }
    return configured
  }

  if (configured.length >= 32) return configured

  const sessionSecret = env.SESSION_SECRET?.trim() || ''
  if (sessionSecret.length >= 32) return sessionSecret

  return LOCAL_INTERNAL_GRAPHQL_SECRET
}

/**
 * Resolve an internal GraphQL endpoint without reflecting request Host or
 * forwarded headers. Portless supplies PORT, so local dev needs no custom URL
 * environment variable. Production may use an explicit internal URL, PORT, or
 * its validated canonical public origin in that order.
 */
export function resolveInternalGraphqlEndpoint(
  env: RuntimeEnvironment = process.env
) {
  const internalUrl = env.INTERNAL_GRAPHQL_URL?.trim()
  if (internalUrl) return configuredUrl(internalUrl, 'INTERNAL_GRAPHQL_URL').href

  const portValue = env.PORT?.trim()
  if (portValue) {
    if (!/^\d+$/.test(portValue) || Number(portValue) < 1 || Number(portValue) > 65535) {
      throw new Error('PORT must be an integer from 1 to 65535')
    }
    return `http://127.0.0.1:${portValue}/api/graphql`
  }

  if (env.NODE_ENV === 'production') {
    const canonicalOrigin = env.NEXT_PUBLIC_SITE_URL?.trim()
    if (!canonicalOrigin) {
      throw new Error('An internal port or canonical site URL is required in production')
    }
    return new URL('/api/graphql', configuredUrl(canonicalOrigin, 'NEXT_PUBLIC_SITE_URL')).href
  }

  return 'http://127.0.0.1:3000/api/graphql'
}
