import { createAuth } from "@keystone-6/auth";
import { config } from "@keystone-6/core";
import "dotenv/config";
import { models } from "./models";
import { statelessSessions } from "@keystone-6/core/session";
import { extendGraphqlSchema } from "./mutations";
import { sendPasswordResetEmail } from "./lib/mail";
import { permissions } from "./access";

const isProduction = process.env.NODE_ENV === "production";
const productionValue = (name: string, fallback: string) => {
  const value = process.env[name]?.trim();
  if (isProduction && !value) throw new Error(`${name} is required in production`);
  return value || fallback;
};

const databaseURL = productionValue("DATABASE_URL", "postgresql://postgres:postgres@127.0.0.1:5432/openfront_dealership_dev");
const sessionSecret = productionValue("SESSION_SECRET", "local-testing-only-session-secret-change-me");
if (isProduction && (sessionSecret.length < 32 || /^(secret|changeme|development|test)/i.test(sessionSecret))) {
  throw new Error("SESSION_SECRET must be a non-placeholder value with at least 32 characters");
}

const sessionConfig = {
  maxAge: 60 * 60 * 8,
  secret: sessionSecret,
};

const rolePermissionFields = `
  id
  name
  canSeeOtherPeople
  canEditOtherPeople
  canManagePeople
  canManageRoles
  canAccessDashboard
  canManageOnboarding
  canManageDealerships
  canManageInventory
  canViewInventory
  canManageLeads
  canViewAllLeads
  canManageDeals
  canApproveDeals
  canManageService
  canViewReports
  canManageFinancing
  canManageTradeIns
`;

const sessionDataFields = `
  name
  email
  role { ${rolePermissionFields} }
  dealerGroupMemberships {
    status
    accessAllRooftops
    dealerGroup { id }
    role { ${rolePermissionFields} }
  }
  rooftopMemberships {
    status
    rooftop { id dealerGroup { id } }
    role { ${rolePermissionFields} }
  }
`;

const sealedSessionStrategy = statelessSessions(sessionConfig);
const sessionStrategy = {
  ...sealedSessionStrategy,
  async get({ context }: { context: any }) {
    const sealed: any = await sealedSessionStrategy.get({ context });
    if (!sealed?.itemId || sealed.listKey !== "User") return undefined;
    const data = await context.sudo().query.User.findOne({ where: { id: sealed.itemId }, query: sessionDataFields });
    return data ? { itemId: sealed.itemId, listKey: "User", data } : undefined;
  },
};

const bucketName = productionValue("S3_BUCKET_NAME", "keystone-test");
const region = productionValue("S3_REGION", "ap-southeast-2");
const accessKeyId = productionValue("S3_ACCESS_KEY_ID", "keystone");
const secretAccessKey = productionValue("S3_SECRET_ACCESS_KEY", "keystone");
const endpoint = productionValue("S3_ENDPOINT", "https://sfo3.digitaloceanspaces.com");

const { withAuth } = createAuth({
  listKey: "User",
  identityField: "email",
  secretField: "password",
  initFirstItem: {
    fields: ["name", "email", "password"],
    itemData: {
      role: {
        create: {
          name: "Admin",
          canSeeOtherPeople: true,
          canEditOtherPeople: true,
          canManagePeople: true,
          canManageRoles: true,
          canAccessDashboard: true,
          canManageOnboarding: true,
          canManageDealerships: true,
          canManageInventory: true,
          canViewInventory: true,
          canManageLeads: true,
          canViewAllLeads: true,
          canManageDeals: true,
          canApproveDeals: true,
          canManageService: true,
          canViewReports: true,
          canManageFinancing: true,
          canManageTradeIns: true,
        },
      },
    },
  },
  passwordResetLink: {
    async sendToken(args) {
      // send the email
      await sendPasswordResetEmail(args.token, args.identity);
    },
  },
  sessionData: sessionDataFields,
});

export default withAuth(
  config({
    db: {
      provider: "postgresql",
      url: databaseURL,
    },
    lists: models,
    storage: {
      my_images: {
        kind: "s3",
        type: "image",
        bucketName,
        region,
        accessKeyId,
        secretAccessKey,
        endpoint,
        signed: { expiry: 5000 },
        forcePathStyle: true,
      },
    },
    ui: {
      isAccessAllowed: ({ session }) => permissions.canAccessDashboard({ session }),
    },
    session: sessionStrategy,
    graphql: {
      extendGraphqlSchema,
    },
  })
);