import { validInternalAuthHeader } from '../lib/graphqlRequestSecurity'
import { requiredText, validEmail } from './submissionUtils'

// Adapted from the canonical User/account boundary: customer registration never
// accepts role, membership, staff flags, or an existing CRM identity to claim.
export async function registerCustomerAccount(_root: unknown, { name, email, password }: { name: string; email: string; password: string }, context: any) {
  const header = context.req?.headers?.['x-openfront-internal-auth']
  if (!validInternalAuthHeader(typeof header === 'string' ? header : null)) throw new Error('Account registration is unavailable')
  if (context.session?.itemId) throw new Error('Sign out before creating an account')
  const configured = await context.prisma.user.count({ where: { role: { is: { canManagePeople: true } } } })
  if (!configured) throw new Error('Account registration is unavailable')
  const cleanName = requiredText(name, 'Name', 200)
  const cleanEmail = validEmail(email).toLowerCase()
  if (typeof password !== 'string' || password.length < 12 || password.length > 200) throw new Error('Password must contain 12–200 characters')
  // This trusted application-only operation is rate-limited before entry. Raw
  // User creation remains staff-only; Keystone hashes the password here.
  const user = await context.sudo().query.User.createOne({
    data: { name: cleanName, email: cleanEmail, password, onboardingStatus: 'dismissed' }, query: 'id',
  })
  return { id: user.id }
}

export function requestingAccountId(context: any): string | null {
  return context.session?.listKey === 'User' && typeof context.session.itemId === 'string' ? context.session.itemId : null
}

// Never use submitted email/phone or a guessed customerId to retrieve history.
// Only records bound to the authenticated account at submission are eligible.
export async function customerRequestHistory(_root: unknown, _args: unknown, context: any) {
  const accountId = requestingAccountId(context)
  if (!accountId) throw new Error('Sign in required')
  const [drives, services] = await Promise.all([
    context.prisma.testDrive.findMany({ where: { requestedById: accountId }, take: 50,
      orderBy: [{ createdAt: 'desc' }, { id: 'desc' }], select: { id: true, scheduledTime: true, completed: true } }),
    context.prisma.serviceAppointment.findMany({ where: { requestedById: accountId }, take: 50,
      orderBy: [{ createdAt: 'desc' }, { id: 'desc' }], select: { id: true, appointmentDate: true, serviceType: true, status: true } }),
  ])
  return [
    ...drives.map((item: any) => ({ id: item.id, kind: 'Test drive', scheduledAt: item.scheduledTime, status: item.completed ? 'completed' : 'requested' })),
    ...services.map((item: any) => ({ id: item.id, kind: 'Service', scheduledAt: item.appointmentDate, status: item.status })),
  ].sort((a, b) => new Date(b.scheduledAt).getTime() - new Date(a.scheduledAt).getTime()).slice(0, 50)
}
