export const DEFAULT_STOREFRONT_LOGO_HUE = '0'

export const STOREFRONT_HUE_PRESETS = [
  { label: '0°', value: '0' },
  { label: '330°', value: '330' },
  { label: '30°', value: '30' },
  { label: '90°', value: '90' },
  { label: '195°', value: '195' },
  { label: '255°', value: '255' },
] as const

export function normalizeStorefrontLogoHue(value: unknown): string {
  const numeric = Number.parseFloat(String(value ?? DEFAULT_STOREFRONT_LOGO_HUE))
  if (!Number.isFinite(numeric)) return DEFAULT_STOREFRONT_LOGO_HUE
  return String(((numeric % 360) + 360) % 360)
}
