export type FinancingProviderSubmission = {
  applicationReference: string
  idempotencyKey: string
  requestedAmountCents: number
  vehicleVin?: string | null
}

export type FinancingProviderSubmissionResult = {
  status: 'queued'
  externalReference: null
  responseSummary: {
    mode: 'operator-recorded'
    externalRequestSent: false
  }
}

export type FinancingProviderAdapter = {
  key: string
  label: string
  submit(input: FinancingProviderSubmission): Promise<FinancingProviderSubmissionResult>
}

const operatorRecordedAdapter: FinancingProviderAdapter = Object.freeze({
  key: 'operator-recorded',
  label: 'Operator-recorded external lender review',
  async submit() {
    return {
      status: 'queued',
      externalReference: null,
      responseSummary: {
        mode: 'operator-recorded',
        externalRequestSent: false,
      },
    }
  },
})

/**
 * Trusted financing adapters are selected only from this source-controlled
 * registry. Database values can select an allowlisted key but can never supply
 * a URL, import path, executable code, or credential.
 */
const FINANCING_PROVIDER_ADAPTERS: Readonly<Record<string, FinancingProviderAdapter>> = Object.freeze({
  [operatorRecordedAdapter.key]: operatorRecordedAdapter,
})

export function resolveFinancingProviderAdapter(providerKey: string) {
  const adapter = FINANCING_PROVIDER_ADAPTERS[providerKey]
  if (!adapter) throw new Error('Unsupported financing provider')
  return adapter
}

// Capability discovery is not provider activation or a legal-validity verdict.
// Only the existing admitted manual adapter is available for prerequisite review.
export function financingPrerequisiteCapability(providerKey: string) {
  resolveFinancingProviderAdapter(providerKey)
  if (providerKey !== 'operator-recorded') throw new Error('Configured provider prerequisite verification is unavailable')
  return { providerKey, configurationVersion: 1, mode: 'operator-recorded' as const,
    humanReviewRequired: true, externalRequestSent: false as const,
    documentSignatureVerified: false as const, legalPolicyVerified: false as const,
    fundingSettlementVerified: false as const }
}

export function financingProviderKeys() {
  return Object.keys(FINANCING_PROVIDER_ADAPTERS)
}
